From 5f660eedae1befa8b1b091e3e644abb9add63c57 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:04:42 +0100
Subject: [PATCH] desktoppackage: open the applet configuration page that was
 requested

When an applet asks for a specific page of its configuration dialog, the
dialog now switches to that page, both when it is first opened and when
it was already open on another page.

CCBUG: 508194
---
 .../configuration/AppletConfiguration.qml        | 16 ++++++++++++++++
 1 file changed, 16 insertions(+)

diff --git a/desktoppackage/contents/configuration/AppletConfiguration.qml b/desktoppackage/contents/configuration/AppletConfiguration.qml
index e452c7917e..506156960d 100644
--- a/desktoppackage/contents/configuration/AppletConfiguration.qml
+++ b/desktoppackage/contents/configuration/AppletConfiguration.qml
@@ -202,6 +202,22 @@ Rectangle {
         }
     }

+    Connections {
+        target: Plasmoid
+
+        function onConfigurationPageRequested(source) {
+            for (let i = 0; i < (configDialog.configModel?.count ?? 0); ++i) {
+                const item = configDialog.configModel.get(i)
+                if (item.visible && String(item.source).endsWith("/" + source)) {
+                    if (root.currentSource != item.source) {
+                        categories.openCategory(item)
+                    }
+                    return
+                }
+            }
+        }
+    }
+
     onCurrentSourceChanged: {
         if (isContainment) {
             configDialog.currentPage = currentSource
-- 
